def even_fibonacci(n):
    """Return the sum of even elements of the fibonacci series"""
    fibo = [1, 1]
    even = 0
    if n < 2 or n > 2_000_000:
        return 0

    while n > 2:
        n -= 1
        f = sum(fibo)
        if f % 2 == 0:
            even += f
        fibo = [fibo[-1], f]

    return even

